content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-30-pet-feeder-007

=== 用户原始指令 (query.txt) ===
帮我整个喂食清单吧 能打勾的 然后余粮数字会变 点一下能跳到app看看天气

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我整个喂食清单吧 能打勾的 然后余粮数字会变 点一下能跳到app看看天气",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "feeder": {
      "title": {
        "type": "string",
        "description": "喂食清单标题。",
        "sampleValue": "喂食清单"
      },
      "tasks": [
        {
          "title": {
            "type": "string",
            "description": "第一项喂食任务名称。",
            "sampleValue": "早粮"
          },
          "done": {
            "type": "boolean",
            "description": "第一项喂食任务是否已勾选。",
            "sampleValue": true
          }
        },
        {
          "title": {
            "type": "string",
            "description": "第二项喂食任务名称。",
            "sampleValue": "晚粮"
          },
          "done": {
            "type": "boolean",
            "description": "第二项喂食任务是否已勾选。",
            "sampleValue": false
          }
        }
      ],
      "remainingText": {
        "type": "string",
        "description": "宠物喂食器当前余粮展示文本。",
        "sampleValue": "2.4kg"
      }
    },
    "data": {
      "weather": {
        "current": {
          "condition": {
            "type": "string",
            "description": "当前天气现象，用于提示点击后查看天气详情。",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/checkmark_calendar_fill.svg",
      "description": "带对勾的日历实心图标，适合作为可勾选清单的识别图标；黑白双色，深色表面上需放在浅色图标底板中。"
    }
  ]
}

